<?php
declare(strict_types=1);

function benchmark_ready(PDO $pdo): bool
{
    try{$pdo->query('SELECT 1 FROM benchmark_configuracoes LIMIT 1');return true;}catch(Throwable){return false;}
}

function benchmark_slug(string $value): string
{
    $value=mb_strtolower(trim($value),'UTF-8');$ascii=@iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$value);
    if(is_string($ascii))$value=$ascii;
    return trim(preg_replace('/[^a-z0-9]+/','-',$value)?:'','-');
}

function benchmark_uploads(array $input): array
{
    if(!isset($input['name']))return [];
    if(!is_array($input['name']))return [$input];
    $files=[];foreach($input['name'] as $i=>$name)$files[]=['name'=>$name,'tmp_name'=>$input['tmp_name'][$i]??'','error'=>$input['error'][$i]??UPLOAD_ERR_NO_FILE,'size'=>$input['size'][$i]??0];
    return $files;
}

function benchmark_store_evidence_files(PDO $pdo,int $configurationId,int $valueId,array $input,array $meta): void
{
    $files=benchmark_uploads($input);if(!$files)return;
    $allowed=['image/jpeg'=>['imagem','jpg',10*1024*1024],'image/png'=>['imagem','png',10*1024*1024],'image/webp'=>['imagem','webp',10*1024*1024],'application/pdf'=>['pdf','pdf',20*1024*1024]];
    $root=dirname(__DIR__).'/public/assets/uploads/benchmark/'.date('Y/m');
    if(!is_dir($root)&&!mkdir($root,0775,true)&&!is_dir($root))throw new RuntimeException('Não foi possível preparar a pasta de evidências.');
    $finfo=new finfo(FILEINFO_MIME_TYPE);$insert=$pdo->prepare('INSERT INTO benchmark_evidencias(titulo,tipo,arquivo,legenda,credito,origem,posicao_captura,escopo,capturado_em,criado_por) VALUES(?,?,?,?,?,?,?,?,?,?)');$linkConfig=$pdo->prepare('INSERT IGNORE INTO benchmark_evidencia_configuracoes(evidencia_id,configuracao_id) VALUES(?,?)');$linkValue=$pdo->prepare('INSERT IGNORE INTO benchmark_evidencia_valores(evidencia_id,valor_id,ordem) VALUES(?,?,?)');
    foreach($files as $order=>$file){$error=(int)($file['error']??UPLOAD_ERR_NO_FILE);if($error===UPLOAD_ERR_NO_FILE)continue;if($error!==UPLOAD_ERR_OK)throw new RuntimeException('Falha ao receber uma evidência.');$tmp=(string)$file['tmp_name'];$mime=(string)$finfo->file($tmp);if(!isset($allowed[$mime]))throw new RuntimeException('Envie somente JPG, PNG, WEBP ou PDF como evidência.');[$type,$ext,$limit]=$allowed[$mime];$size=(int)($file['size']??0);if($size<1||$size>$limit)throw new RuntimeException('Uma evidência excede o tamanho permitido.');$name=bin2hex(random_bytes(18)).'.'.$ext;$absolute=$root.'/'.$name;if(!move_uploaded_file($tmp,$absolute))throw new RuntimeException('Não foi possível guardar uma evidência.');$relative='/public/assets/uploads/benchmark/'.date('Y/m').'/'.$name;$title=trim((string)($meta['titulo']??''))?:pathinfo((string)$file['name'],PATHINFO_FILENAME);$insert->execute([mb_substr($title,0,200),$type,$relative,trim((string)($meta['legenda']??''))?:null,trim((string)($meta['credito']??''))?:null,trim((string)($meta['origem']??''))?:null,trim((string)($meta['posicao_captura']??''))?:null,trim((string)($meta['escopo']??''))?:null,trim((string)($meta['capturado_em']??''))?:null,(int)(user()['id']??0)]);$id=(int)$pdo->lastInsertId();$linkConfig->execute([$id,$configurationId]);$linkValue->execute([$id,$valueId,$order]);}
}

function benchmark_store_evidence_link(PDO $pdo,int $configurationId,int $valueId,array $meta): void
{
    $url=trim((string)($meta['evidencia_url']??''));if($url==='')return;
    if(!filter_var($url,FILTER_VALIDATE_URL)||!in_array(strtolower((string)parse_url($url,PHP_URL_SCHEME)),['http','https'],true))throw new RuntimeException('Informe uma URL de evidência HTTP ou HTTPS válida.');
    $stmt=$pdo->prepare('INSERT INTO benchmark_evidencias(titulo,tipo,url,legenda,credito,origem,posicao_captura,escopo,capturado_em,criado_por) VALUES(?,?,?,?,?,?,?,?,?,?)');
    $stmt->execute([mb_substr(trim((string)($meta['titulo']??''))?:'Evidência externa',0,200),'link',$url,trim((string)($meta['legenda']??''))?:null,trim((string)($meta['credito']??''))?:null,trim((string)($meta['origem']??''))?:null,trim((string)($meta['posicao_captura']??''))?:null,trim((string)($meta['escopo']??''))?:null,trim((string)($meta['capturado_em']??''))?:null,(int)(user()['id']??0)]);
    $id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT IGNORE INTO benchmark_evidencia_configuracoes(evidencia_id,configuracao_id) VALUES(?,?)')->execute([$id,$configurationId]);$pdo->prepare('INSERT IGNORE INTO benchmark_evidencia_valores(evidencia_id,valor_id,ordem) VALUES(?,?,999)')->execute([$id,$valueId]);
}

function benchmark_analysis_origin_ready(PDO $pdo): bool
{
    static $ready=null;if($ready!==null)return $ready;
    $stmt=$pdo->prepare("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='benchmark_analises' AND COLUMN_NAME='origem'");$stmt->execute();return $ready=(bool)$stmt->fetchColumn();
}

function benchmark_remove_evidence_file(?string $file): void
{
    if(!$file||!str_starts_with($file,'/public/assets/uploads/benchmark/'))return;
    $public=dirname(__DIR__).'/public';$relative=(string)preg_replace('#^/public#','',$file);$absolute=$public.str_replace('/',DIRECTORY_SEPARATOR,$relative);
    $base=realpath($public.'/assets/uploads/benchmark');$directory=realpath(dirname($absolute));
    if($base&&$directory&&str_starts_with(strtolower($directory),strtolower($base))&&is_file($absolute))@unlink($absolute);
}

