function load_benchmark_page(): array
{
    $pdo=db();$data=['ready'=>false,'analysis_origin_ready'=>false,'categories'=>[],'attributes'=>[],'configurations'=>[],'values'=>[],'analyses'=>[],'models'=>[],'stats'=>[]];if(!$pdo||!benchmark_ready($pdo))return $data;$data['ready']=true;$data['analysis_origin_ready']=benchmark_analysis_origin_ready($pdo);
    $data['categories']=$pdo->query('SELECT bc.*,(SELECT COUNT(*) FROM benchmark_atributos ba WHERE ba.categoria_id=bc.id AND ba.ativo=1) atributos FROM benchmark_categorias bc ORDER BY bc.ordem,bc.nome')->fetchAll();
    $data['attributes']=$pdo->query('SELECT ba.*,bc.nome categoria_nome FROM benchmark_atributos ba JOIN benchmark_categorias bc ON bc.id=ba.categoria_id ORDER BY bc.ordem,ba.ordem,ba.nome')->fetchAll();
    $data['models']=$pdo->query('SELECT m.id,m.nome,f.nome familia_nome,ma.nome marca_nome,f.tipo_veiculo FROM modelos m JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id WHERE m.ativo=1 ORDER BY ma.nome,f.nome,m.nome')->fetchAll();
    $data['configurations']=$pdo->query("SELECT bc.*,m.nome modelo_nome,m.imagem modelo_imagem,f.nome familia_nome,ma.nome marca_nome,ma.slug marca_slug,(SELECT COUNT(*) FROM benchmark_valores bv WHERE bv.configuracao_id=bc.id) observacoes,(SELECT COUNT(*) FROM benchmark_evidencia_configuracoes bec WHERE bec.configuracao_id=bc.id) evidencias FROM benchmark_configuracoes bc JOIN modelos m ON m.id=bc.modelo_id JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id ORDER BY bc.ativo DESC,ma.nome,f.nome,m.nome,bc.nome")->fetchAll();
    $values=$pdo->query("SELECT bv.*,ba.nome atributo_nome,ba.tipo atributo_tipo,ba.criterio,ba.categoria_id,bc.nome categoria_nome,c.nome configuracao_nome,m.nome modelo_nome,ma.nome marca_nome FROM benchmark_valores bv JOIN benchmark_atributos ba ON ba.id=bv.atributo_id JOIN benchmark_categorias bc ON bc.id=ba.categoria_id JOIN benchmark_configuracoes c ON c.id=bv.configuracao_id JOIN modelos m ON m.id=c.modelo_id JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id ORDER BY bc.ordem,ba.ordem")->fetchAll();$galleryStmt=$pdo->prepare('SELECT be.* FROM benchmark_evidencias be JOIN benchmark_evidencia_valores bev ON bev.evidencia_id=be.id WHERE bev.valor_id=? ORDER BY bev.ordem,be.id');foreach($values as &$value){$galleryStmt->execute([(int)$value['id']]);$value['gallery']=$galleryStmt->fetchAll();}$data['values']=$values;
    $originSelect=$data['analysis_origin_ready']?'a.origem':"CASE WHEN a.criado_por IS NULL THEN 'importacao' ELSE 'manual' END";$data['analyses']=$pdo->query("SELECT a.*,{$originSelect} origem_analise,(SELECT GROUP_CONCAT(ac.configuracao_id ORDER BY ac.configuracao_id) FROM benchmark_analise_configuracoes ac WHERE ac.analise_id=a.id) configuracoes_ids,(SELECT GROUP_CONCAT(CONCAT(ma.nome,' ',m.nome) ORDER BY ma.nome,m.nome SEPARATOR ' · ') FROM benchmark_analise_configuracoes ac JOIN benchmark_configuracoes c ON c.id=ac.configuracao_id JOIN modelos m ON m.id=c.modelo_id JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id WHERE ac.analise_id=a.id) configuracoes_nomes FROM benchmark_analises a ORDER BY FIELD(a.status,'em_analise','validada','planejada','rascunho','concluida','arquivada'),a.atualizado_em DESC")->fetchAll();
    $validated=0;$evidence=0;foreach($values as $v){if($v['status_revisao']==='validado')$validated++;$evidence+=count($v['gallery']);}$data['stats']=['configurations'=>count($data['configurations']),'attributes'=>count($data['attributes']),'observations'=>count($values),'validated'=>$validated,'evidence'=>$evidence,'coverage'=>count($data['configurations'])&&count($data['attributes'])?(int)round(count($values)/(count($data['configurations'])*count($data['attributes']))*100):0];
    return $data;
}
